CREATE TABLE "competition_status_history" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "competition_id" bigint NOT NULL,
    "from_status" varchar(30),
    "to_status" varchar(30) NOT NULL,
    "changed_by" bigint NOT NULL,
    "changed_at" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "competition_status_history_competition_fkey"
        FOREIGN KEY ("competition_id") REFERENCES "competition" ("id") ON DELETE CASCADE,
    CONSTRAINT "competition_status_history_user_fkey"
        FOREIGN KEY ("changed_by") REFERENCES "user" ("id")
);

CREATE INDEX "competition_status_history_competition_idx"
    ON "competition_status_history" ("competition_id", "changed_at", "id");

INSERT INTO "competition_status_history" ("competition_id", "from_status", "to_status", "changed_by")
SELECT "id", NULL, "status", "created_by" FROM "competition";
